import bpy

# ---- shift shelf from (0.3,2.45) to (-1.1,2.5) ----
for o in bpy.data.objects:
    if o.name.startswith('sh_'):
        o.location.x -= 1.4
        o.location.y += 0.05

# ---- shift dresser from (1.9,1.1) to (0.9,0.5) ----
for o in bpy.data.objects:
    if o.name.startswith('dr_'):
        o.location.x -= 1.0
        o.location.y -= 0.6

# ---- add bevels to nightstand bodies/drawers ----
for o in bpy.data.objects:
    if o.name.startswith('ns_') and 'knob' not in o.name:
        if not any(m.type=='BEVEL' for m in o.modifiers):
            md = o.modifiers.new('bevel','BEVEL'); md.width=0.008; md.segments=2
print("shifted")

import bpy
