    if o.name.startswith('sh_'):
        o.location.x += 2.3; o.location.y -= 0.2
# dresser currently (0.9,0.5) -> (2.4,1.1): dx +1.5, dy +0.6
for o in bpy.data.objects:
    if o.name.startswith('dr_'):
        o.location.x += 1.5; o.location.y += 0.6
print("ok")

import bpy

# apply modifiers for clean export
for o in list(bpy.data.objects):
    if o.type == 'MESH' and o.modifiers:
        bpy.context.view_layer.objects.active = o
        for md in list(o.modifiers):
            try: bpy.ops.object.modifier_apply(modifier=md.name)
            except Exception as e: print('skip', o.name, e)

# sanity: report bounding boxes of key groups and min-z
import mathutils
groups = {'lb':'light bed','db':'dark bed','ns':'nightstand','sh':'shelf','dr':'dresser','mc':'cabinet','fl':'floor lamp'}
mins = {}
for o in bpy.data.objects:
    if o.type!='MESH': continue
    p = o.name.split('_')[0]
    if p in groups:
        for c in o.bound_box:
            w = o.matrix_world @ mathutils.Vector(c)
            if p not in mins or w.z < mins[p]: mins[p] = w.z
print({groups[k]: round(v,3) for k,v in mins.items()})

# save
bpy.ops.wm.save_as_mainfile(filepath='/app/output/scene.blend')
print('SAVED, total objects:', len(bpy.data.objects))

